```yaml
name: Auto Assign Milestone

on:
  pull_request:
    types: [opened, synchronize, reopened, edited, closed]

permissions:
  pull-requests: write
  contents: read

jobs:
  assign-milestone:
    runs-on: ubuntu-latest
    steps:
      - name: Assign milestone
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            if (!pr) return;

            const baseBranch = pr.base.ref;
            let milestoneName = null;

            if (baseBranch === 'main') {
              // For main, assign the 9.5 milestone
              milestoneName = '9.5';
            } else if (baseBranch.startsWith('release/')) {
              // For release branches, map release/9.4 -> 9.4.1
              const releaseVersion = baseBranch.split('/')[1];
              milestoneName = `${releaseVersion}.1`;
            }

            if (!milestoneName) return;

            const { owner, repo } = context.repo;
            const issueNumber = pr.number;

            // Find the milestone by title
            const milestones = await github.rest.issues.listMilestones({
              owner,
              repo,
              state: 'all',
              per_page: 100
            });

            const milestone = milestones.data.find(m => m.title === milestoneName);
            if (!milestone) {
              console.log(`Milestone "${milestoneName}" not found`);
              return;
            }

            // Assign the milestone to the PR
            await github.rest.issues.update({
              owner,
              repo,
              issue_number: issueNumber,
              milestone: milestone.number
            });

            console.log(`Assigned milestone "${milestoneName}" to PR #${issueNumber}`);
          result-encoding: string
